-- Reviewed invariants not expressible as Prisma partial indexes.
CREATE UNIQUE INDEX "one_superadmin" ON "User" ("role") WHERE "role" = 'SUPERADMIN';
CREATE UNIQUE INDEX "one_current_session" ON "AcademicSession" ("schoolId") WHERE "current";
CREATE UNIQUE INDEX "one_active_teacher_assignment" ON "TeacherAssignment" ("schoolId", "sessionId", "teacherId") WHERE "endedAt" IS NULL;
ALTER TABLE "User" ADD CONSTRAINT "User_id_school_unique" UNIQUE ("id", "schoolId");
ALTER TABLE "School" ADD CONSTRAINT "admission_counter_positive" CHECK ("nextAdmission" > 0);
ALTER TABLE "AcademicSession" ADD CONSTRAINT "session_dates" CHECK ("endDate" > "startDate");
ALTER TABLE "ClassOffering" ADD CONSTRAINT "capacity_positive" CHECK ("capacity" > 0);
ALTER TABLE "TeacherAssignment" ADD CONSTRAINT "assignment_dates" CHECK ("endDate" IS NULL OR "endDate" >= "startDate");
ALTER TABLE "User" ADD CONSTRAINT "User_school_fk" FOREIGN KEY ("schoolId") REFERENCES "School" ("id") ON DELETE RESTRICT;
ALTER TABLE "AcademicSession" ADD CONSTRAINT "Session_school_fk" FOREIGN KEY ("schoolId") REFERENCES "School" ("id") ON DELETE RESTRICT;
ALTER TABLE "Subject" ADD CONSTRAINT "Subject_school_fk" FOREIGN KEY ("schoolId") REFERENCES "School" ("id") ON DELETE RESTRICT;
ALTER TABLE "Family" ADD CONSTRAINT "Family_school_fk" FOREIGN KEY ("schoolId") REFERENCES "School" ("id") ON DELETE RESTRICT;
ALTER TABLE "ClassOffering" ADD CONSTRAINT "Class_session_fk" FOREIGN KEY ("sessionId", "schoolId") REFERENCES "AcademicSession" ("id", "schoolId") ON DELETE RESTRICT;
ALTER TABLE "ClassOffering" ADD CONSTRAINT "Class_next_fk" FOREIGN KEY ("nextClassId", "schoolId") REFERENCES "ClassOffering" ("id", "schoolId") ON DELETE RESTRICT;
ALTER TABLE "Guardian" ADD CONSTRAINT "Guardian_family_fk" FOREIGN KEY ("familyId", "schoolId") REFERENCES "Family" ("id", "schoolId") ON DELETE RESTRICT;
ALTER TABLE "Student" ADD CONSTRAINT "Student_family_fk" FOREIGN KEY ("familyId", "schoolId") REFERENCES "Family" ("id", "schoolId") ON DELETE RESTRICT;
ALTER TABLE "Application" ADD CONSTRAINT "Application_session_fk" FOREIGN KEY ("sessionId", "schoolId") REFERENCES "AcademicSession" ("id", "schoolId") ON DELETE RESTRICT;
ALTER TABLE "Application" ADD CONSTRAINT "Application_student_fk" FOREIGN KEY ("studentId", "schoolId") REFERENCES "Student" ("id", "schoolId") ON DELETE RESTRICT;
ALTER TABLE "Enrollment" ADD CONSTRAINT "Enrollment_student_fk" FOREIGN KEY ("studentId", "schoolId") REFERENCES "Student" ("id", "schoolId") ON DELETE RESTRICT;
ALTER TABLE "Enrollment" ADD CONSTRAINT "Enrollment_session_fk" FOREIGN KEY ("sessionId", "schoolId") REFERENCES "AcademicSession" ("id", "schoolId") ON DELETE RESTRICT;
ALTER TABLE "Enrollment" ADD CONSTRAINT "Enrollment_class_fk" FOREIGN KEY ("classId", "schoolId") REFERENCES "ClassOffering" ("id", "schoolId") ON DELETE RESTRICT;
ALTER TABLE "Application" ADD CONSTRAINT "Application_id_school_unique" UNIQUE ("id", "schoolId");
ALTER TABLE "TeacherAssignment" ADD CONSTRAINT "Assignment_teacher_fk" FOREIGN KEY ("teacherId", "schoolId") REFERENCES "User" ("id", "schoolId") ON DELETE RESTRICT;
ALTER TABLE "TeacherAssignment" ADD CONSTRAINT "Assignment_class_fk" FOREIGN KEY ("classId", "schoolId") REFERENCES "ClassOffering" ("id", "schoolId") ON DELETE RESTRICT;
ALTER TABLE "Document" ADD CONSTRAINT "Document_student_fk" FOREIGN KEY ("studentId", "schoolId") REFERENCES "Student" ("id", "schoolId") ON DELETE RESTRICT;
ALTER TABLE "Document" ADD CONSTRAINT "Document_application_fk" FOREIGN KEY ("applicationId", "schoolId") REFERENCES "Application" ("id", "schoolId") ON DELETE RESTRICT;
ALTER TABLE "Document" ADD CONSTRAINT "document_owner" CHECK ("studentId" IS NOT NULL OR "applicationId" IS NOT NULL);
ALTER TABLE "AuditEvent" ADD CONSTRAINT "Audit_actor_fk" FOREIGN KEY ("actorId", "schoolId") REFERENCES "User" ("id", "schoolId") ON DELETE RESTRICT;
